scripts.段芙蓉对话.txt:
// 和段芙蓉对话

	If ($Event == 270) @Event270;
	Return;
	
@Event270:	
	Say("段芙蓉：你不要拦着我，我一定要回去！", 204);
	Say("小雷：不行不行不行！你现在这样回去，那不是送死吗？", 69);
	Say("段芙蓉：我不信，不信我爹……已经不在了，我一定要回去看个明白，你别拦着我！", 204);
	Say("小雷：哎哟，芙蓉姐姐、芙蓉姑姑、芙蓉奶奶！你要我怎么说你才会相信？", 69);
	Sleep(500);
	Say("独孤剑：小雷！", 1);
	Say("独孤剑：段姑娘！", 1);
	Say("小雷：哎呀，救星到了。", 69);
	NpcGoto("小雷", 3, 15);
	SetNpcDir("小雷", 7);
	PlayerGoto(3, 17);
	SetPlayerDir(3);
	SetNpcKind("张琳心", 1);
	NpcGoto("张琳心", 4, 16);
	SetNpcDir("张琳心", 3);
	Say("段芙蓉：这位公子是……", 204);
	Say("独孤剑：在下衡山独孤剑，这位姑娘是禁军都指挥使张大人之女张琳心。", 1);
	Say("段芙蓉：芙蓉见过二位。", 204);
	Say("独孤剑：段姑娘，我们是受令尊临终前的嘱托来的。", 1);
	Say("段芙蓉：临终？难道我爹……他真的……", 204);
	Say("独孤剑：他老人家确实已经去世了。", 1);
	Say("小雷：我早就说过我没骗你了。", 69);
	Say("段芙蓉：不！不！我不相信！不可能！我爹说好过两天就来接我回去的！他不会骗我的，不会的……呜呜——", 204);
	Say("独孤剑：段姑娘，你爹是被吕文才所害，只恨我们去晚了一步……", 9);
	Say("段芙蓉：吕文才这个狗官！他几次强迫我不成，想不到……我去跟他拼了——", 204);
	Say("张琳心：段姑娘，这位独孤大哥已经手刃吕文才，替你爹爹报了仇。", 27);
	Say("段芙蓉：多谢独孤公子，只是我爹——", 204);
	Say("张琳心：段姑娘，你不要过分哀伤，我也刚刚遭受了同样的丧父之痛，你的心情我很理解……我能叫你一声“妹妹”吗？", 24);
	Say("小雷：好啊，这样最好了。", 69);
	Say("段芙蓉：姐姐…… ", 204);
	Say("张琳心：好妹妹！", 21);
	Say("段芙蓉：张姐姐、独孤公子，多谢你们替我报了父仇，芙蓉无以为报，就将这柄越女宝剑送给你们。", 67);
	Say("独孤剑：这是你的家传宝物，我们怎么能接受呢？还请芙蓉妹妹收回成命。", 1);
	Say("段芙蓉：其实我们家并无习武之人，爹爹因是炼剑之人，故此收集一些成名剑器。现爹爹已去，小女子若持此绝世宝剑反会惹杀身之祸，况且二位为我爹爹报仇雪恨，理当受此宝剑。", 67);
	Say("张琳心：芙蓉妹妹既然这样说，我们就收下了。", 21);
	Say("小雷：是啊！宝剑赠侠士，红粉配佳人，这是理所当然的。", 69);
	Say("张琳心：对了，芙蓉妹妹，你爹临终时嘱咐我们送你去成都姑妈家。", 21);
	Say("段芙蓉：这么麻烦你们，真是……", 67);
	Say("小雷：不麻烦不麻烦，替美人效劳，小叫化求之不得呀！", 69);
	Say("张琳心：芙蓉妹妹，不必见外，我们反正要去长安附近的华山，顺路而已。", 21);
	Say("小雷：独孤大哥和张姑娘既然有要事去华山，那就由我送芙蓉姑娘去成都好了，我正好也想去成都玩玩，芙蓉姑娘，怎样？", 69);
	Say("段芙蓉：除非你不再这样油腔滑调。", 67);
	Say("小雷：冤枉！冤枉啊！我小叫化说话一向最实在啦。", 69);
	Say("张琳心：芙蓉妹妹，这位小兄弟说话虽然不拘小节，但却是一个性情中人，为人热心快肠，由他护送你去成都，我们也很放心。", 21);
	Say("段芙蓉：那……你得答应我一件事！", 67);
	Say("小雷：别说一件，就是一千件我也答应你！", 69);
	Say("段芙蓉：你要答应我的就是这一条：一路上都不准胡言乱语！", 67);
	Say("小雷：不准说话……这不比死了还难受……", 69);
	Say("段芙蓉：那你到底答不答应？", 67);
	Say("小雷：答应答应！听芙蓉妹妹说话可比听我自己说话受用多了！哈哈……", 69);
	Say("独孤剑：那我们现在就启程吧。", 1);	
	Say("段芙蓉：好，我们从水路走，外公可以送我们一程。", 67);
	AddGoods("Goods057_越女剑.ini");
	
	FadeOut();
	SetNpcKind("张琳心", 3);  
	SetNpcRelation("张琳心", 2);
	SetNpcKind("小雷", 3);  
	SetNpcRelation("小雷", 2);
	SetNpcKind("段芙蓉", 3);  
	SetNpcRelation("段芙蓉", 2);
	LoadMap("map034_1_海边小渔村.map");
	LoadNpc("map034_1.npc");
	LoadObj("map034_1.obj");
	SetPlayerPos(31, 44);
	SetPlayerDir(7);
	SetNpcKind("张琳心", 1);
	SetNpcKind("小雷", 1);  
	SetNpcKind("段芙蓉", 1);  
	Sleep(500);
	SetNpcPos("张琳心", 30, 43);
	SetNpcDir("张琳心", 7);
	SetNpcPos("小雷", 31, 42);
	SetNpcDir("小雷", 0);
	SetNpcPos("段芙蓉", 31, 43);
	SetNpcDir("段芙蓉", 0);
	FadeIn();
	Say("老王：我这外孙女就拜托你们送她去成都了，大家上船吧，我送你们一程。", 65);
	
	Sleep(1000);
	FadeOut();
	StopMusic();
	PlayMusic("前途.mp3");
	SetNpcKind("张琳心", 3);
	SetNpcKind("小雷", 3);  
	SetNpcKind("段芙蓉", 3);  
	LoadMap("map044_石塘镇.map");
	LoadNpc("map044.npc");
	LoadObj("map044.obj");
	SetPlayerPos(5, 75);
	SetPlayerDir(1);
	SetNpcKind("张琳心", 1);
	SetNpcKind("小雷", 1);  
	SetNpcKind("段芙蓉", 1);  
	Sleep(500);
	SetNpcPos("张琳心", 6, 76);
	SetNpcDir("张琳心", 2);
	SetNpcPos("小雷", 5, 76);
	SetNpcDir("小雷", 5);
	SetNpcPos("段芙蓉", 5, 77);
	SetNpcDir("段芙蓉", 5);
	FadeIn();
	Say("独孤剑：到了石塘镇，前面不远就是华山了，我们就此别过吧，小雷，段姑娘就拜托给你了。", 1);
	Say("小雷：我小雷办事，你放心好了！", 69);
	Say("段芙蓉：多谢二位了。", 67);
	Say("张琳心：妹妹不要见外，一路保重。", 21);
	SetNpcKind("张琳心", 3);
	SetNpcScript("张琳心", "张琳心对话.txt");		
	SetNpcScript("小雷", "小雷对话.txt");		
	SetNpcScript("段芙蓉", "段芙蓉对话.txt");	
	Assign($Event, 280);
	Memo("独孤剑、张琳心和小雷三人一起来到海边小渔村老王家，找到段铁匠之女段芙蓉。四人一起乘船来到石塘镇，由小雷继续护送芙蓉到成都去投奔姑妈，独孤剑和张琳心二人前往华山。");	
	Return;

