@Event125:
	Say("贾老实：现在算来，蛋孵鸡，鸡生蛋，那只鸡蛋可以孵出上万只鸡，他这辈子都无法偿还了，哈哈……", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.渔夫老王对话.txt:
//和渔夫老王的对话

	If ($Event << 120) @Eventlessthan120;
	If ($Event == 120) @Event120;
	If ($Event >= 180) @Evnet180;
	If ($Event == 270) @Event270;
	If ($Event == 280) @Event280;
	
	Say("老王：公子还要出海吗？", 65);
	Say("独孤剑：哦，我只是来看看您，不出海。", 1);
	Say("老王：公子真是有心了，老汉心领了。", 65);
	Return;

@Eventlessthan120:
	If ($TalkLaow == 0) @TalkLaow0;
	If ($TalkLaow == 1) @TalkLaow1;	
@TalkLaow0:
	Say("独孤剑：王老伯，在下有要紧的事，请带我去一趟碧霞岛。", 1);
	Say("渔夫老王：我一天只出一次海，今儿已经出过了，就算是皇帝来请，我也不会再出海。", 65);
	Memo("来到海边小渔村，去碧霞岛得坐船，找到船夫老王，可是他不肯出海。");
	SetMapTrap(1, "trap01.txt");
	Assign($Event, 90);	
	Assign($TalkLaow, 1);
	Return;
@TalkLaow1:
	Say("渔夫老王：就算是皇帝来请，我也不会出海的。", 65);
	Return;

@Event120:
	Return;	

@Event180:
	If ($TalkLaowang == 0) @TalkLaowang0;
	If ($TalkLaowang == 1) @TalkLaowang1;
 @TalkLaowang0:
	Say("独孤剑：老王，听说你当年吃过别人一只鸡蛋？", 1);
	Say("老王：不错。", 65);
	Say("独孤剑：那只鸡蛋是生的还是熟的？", 1);
	Say("老王：当然是熟的。", 65);
	Say("独孤剑：熟鸡蛋能不能孵出小鸡来？", 1);
	Say("老王：不能。", 65);	
	Say("独孤剑：那么你欠他什么？", 1);
	Say("老王：欠他什么？……，对啊，我欠他的不过是只熟鸡蛋，哈哈，哈哈，多谢公子指点。", 65);
	Say("独孤剑：是我告诉了张姑娘，张姑娘点破你的。", 2);
	Say("老王：总之是多谢你们了。公子什么时候要船，我就什么时候出海。", 65);
	Return;
 @TalkLaowang1:
	Say("渔夫老王：公子还要出海吗？", 65);
	Say("独孤剑：哦，我只是来看看您，不出海。", 1);
	Say("渔夫老王：公子真是有心了，老汉心领了。", 65);
	Return;

@Event270:
	Say("老王：公子和姑娘来了？这位是老汉的外孙女儿芙蓉。芙蓉，过来见独孤公子和张姑娘。", 65);
	Return;

@Event280；
	Say("老王：唉，想不到……既然这样，老汉就用船送你们一程。", 65);
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map044_石塘镇.map");
	LoadNpc("map044.npc");
	LoadObj("map044.obj");
	AddNpc("渔夫老王.ini",3,79,5); //老王的文件名
	AddNpc("段芙蓉.ini",5,78,2);
	SetPlayerPos(4,77);
	SetPlayerDir(1);
	SetNpcPos("张琳心",4,76);
	SetNpcDir("张琳心",0);
	SetNpcPos("小雷",5,77);
	SetNpcDir("小雷",1);
	PlayMusic(); //待定
	FadeIn();
	Say("老王：老汉就只能送到这里了。", 65)；
	Say("独孤剑：有劳您了。前面不远就是华山了，我们就此别过。段姑娘好好保重！", 2);
	Say("段芙蓉：多谢二位了。", 67)；
	Say("张琳心：妹妹不要见外，我们后会有期。", 21)；
	Say("小雷：唉，小叫化要是能继续当叫化就好了，就可以和你们游山逛水。算了，不说了，后会有期。", 69)；
	SetNpcKind("小雷",0);
	Memo("独孤剑、张琳心和小雷三人一起来到海边小渔村的老王家里，见到了段铁匠的女儿段芙蓉，独孤剑告知了她父亲之死。四人乘船来到石塘镇海边，然后分开行动，由老王和小雷继续护送芙蓉到成都去投奔姑妈，独孤剑和张琳心二人前往华山。")；
	Return;

